    actions: Vec<AnyElement>,
    cx: &mut Context<PromptMode>,
) -> AnyElement {
    let theme = cx.theme();
    let label = if expanded {
        self.back.to_string()
    } else {
        match count {
            0 => format!("No {}", self.plural),
